@Service
public class ProductsConfigurationsService {

    @Autowired
    ProductsConfigurationsDAO productsConfigurationsDAO;

    @Autowired
    ProductsService productsService;

    @Autowired
    ConfigurationEvaluator configurationEvaluator;

    public List<String> getConfigurationsNamesForProduct(String productName) {
        List<String> configurationsForProduct = new ArrayList<String>();

        for (ProductConfiguration productConfiguration : productsConfigurationsDAO.findByProductName(productName)) {
            configurationsForProduct.add(productConfiguration.getName());
        }

        return configurationsForProduct;
    }

    public ProductConfiguration findByNameAndProductName(String productName, String configurationName) {
        return productsConfigurationsDAO.findByNameAndProductName(productName, configurationName);
    }

    public List<String> getConfigurationActivedFeaturesNames(String productName, String configurationName) {
        ProductConfiguration productConfiguration = productsConfigurationsDAO.findByNameAndProductName(productName, configurationName);
        List<String> featureNames = new ArrayList<String>();
        for (Feature feature : productConfiguration.getActivedFeatures()) {
            featureNames.add(feature.getName());
        }
        return featureNames;
    }


    public void add(String productName, String configurationName) {
        Product product = productsService.findByName(productName);

        ProductConfiguration configuration = new ProductConfiguration();
        configuration.setName(configurationName);
        configuration.setProduct(product);
        productsConfigurationsDAO.insert(configuration);
    }

    public void deleteByName(String productName, String configurationName) {
        productsConfigurationsDAO.deleteConfigurationForProduct(productName, configurationName);

    }

    @Transactional
    public EvaluationResult removeFeatureFromConfiguration(String productName, String configurationName, String featureName) {
        ProductConfiguration configuration = productsConfigurationsDAO.findByNameAndProductName(productName, configurationName);
        configuration.deactive(featureName);

        return evaluateAndUpdateConfiguration(configuration);
    }


    @Transactional
    public EvaluationResult addFeatureFromConfiguration(String productName, String configurationName, String featureName) {
        ProductConfiguration configuration = productsConfigurationsDAO.findByNameAndProductName(productName, configurationName);
        if (configuration.hasActiveFeature(featureName)) {
            throw new DuplicatedObjectException(featureName);
        }
        configuration.active(featureName);

        return evaluateAndUpdateConfiguration(configuration);
    }

    private EvaluationResult evaluateAndUpdateConfiguration(ProductConfiguration configuration) {
        Product product = configuration.getProduct();
        EvaluationResult evaluationResult = configurationEvaluator.evaluateConfiguration(configuration, product.getProductFeatureConstraints());
        configuration.setValid(evaluationResult.isValid);
        return evaluationResult;
    }
}

@Service
public class ProductsService {

    @Autowired
    ProductsDAO productsDAO;

    @Autowired
    ProductsConfigurationsDAO productsConfigurationsDAO;


    public List<String> getAllProductNames() {
        List<String> allProducts = new ArrayList<String>();

        for (Product product : productsDAO.findAll()) {
            allProducts.add(product.getName());
        }

        return allProducts;
    }

    public Product findByName(String productName) {
        return productsDAO.findByName(productName);
    }

    public void deleteByName(String productName) {
        productsConfigurationsDAO.deleteConfigurationsForProduct(productName);
        productsDAO.deleteConstraintsForProduct(productName);
        productsDAO.deleteByName(productName);
    }

    public void add(String productName) {
        Product product = new Product();
        product.setName(productName);
        productsDAO.insert(product);
    }

    public Set<Feature> getFeaturesForProduct(String productName) {
        Product product = findByName(productName);
        return product.getProductFeatures();
    }

    public void addFeatureToProduct(String productName, String featureName, String featureDescription) {
        Product product = findByName(productName);
        if (product.hasFeatureNamed(featureName)) {
            throw new DuplicatedObjectException(featureName);
        }
        Feature feature = Feature.withName(product, featureName);
        feature.setDescription(featureDescription);
        productsDAO.insertFeature(feature);
    }

    @Transactional
    public Feature updateFeatureOfProduct(String productName, String featureName, String featureDescription) {
        Product product = productsDAO.findByName(productName);
        Feature feature = product.findProductFeatureByName(featureName);
        feature.setDescription(featureDescription);
        return feature;
    }

    @Transactional
    public void deleteFeatureOfProduct(String productName, String featureName) {
        Product product = productsDAO.findByName(productName);
        Feature feature = product.findProductFeatureByName(featureName);

        for (ProductConfiguration productConfiguration : productsConfigurationsDAO.findConfigurationsWithFeatureActive(feature)) {
            productConfiguration.getActivedFeatures().remove(feature);
        }

        productsDAO.deleteFeature(feature);
    }

    public FeatureConstraint addRequiresConstraintToProduct(String productName, String sourceFeatureName, String requiredFeatureName) {
        Product product = productsDAO.findByName(productName);

        ConstraintRequires constraintRequires = new ConstraintRequires(sourceFeatureName, requiredFeatureName);
        constraintRequires.setForProduct(product);
        productsDAO.insertConstraint(constraintRequires);

        return constraintRequires;
    }

    public void deleteConstraintFromProduct(String productName, Long constraintId) {
        productsDAO.deleteConstraintForProduct(productName, constraintId);
    }

    public FeatureConstraint addExcludesConstraintToProduct(String productName, String sourceFeatureName, String excludedFeatureName) {
        Product product = productsDAO.findByName(productName);

        ConstraintExcludes constraintExcludes = new ConstraintExcludes(sourceFeatureName, excludedFeatureName);
        constraintExcludes.setForProduct(product);
        productsDAO.insertConstraint(constraintExcludes);

        return constraintExcludes;
    }
}

@Repository
public class ProductsConfigurationsDAO {

    @PersistenceContext
    private EntityManager entityManager;

    QProductConfiguration qProductConfiguration = QProductConfiguration.productConfiguration;
    QProduct qProduct = QProduct.product;

    public List<ProductConfiguration> findByProductName(String productName) {


        JPAQuery query = new JPAQuery(entityManager);
        query.from(qProductConfiguration)
                .innerJoin(qProductConfiguration.product, qProduct)
                .where(qProduct.name.eq(productName));
        return query.list(qProductConfiguration);
    }

    public ProductConfiguration findByNameAndProductName(String productName, String configurationName) {
        QProduct qProduct = QProduct.product;


        JPAQuery query = new JPAQuery(entityManager);
        query.from(qProductConfiguration)
                .innerJoin(qProductConfiguration.product, qProduct)
                .where(qProduct.name.eq(productName)
                        .and(qProductConfiguration.name.eq(configurationName)));
        return query.singleResult(qProductConfiguration);
    }

    @Transactional
    public void deleteConfigurationsForProduct(String productName) {
        for (ProductConfiguration productConfiguration : findByProductName(productName)) {
            entityManager.remove(productConfiguration);
        }

    }

    public List<ProductConfiguration> findConfigurationsWithFeatureActive(Feature feature) {
        JPAQuery query = new JPAQuery(entityManager);
        query.from(qProductConfiguration)
                .where(qProductConfiguration.activedFeatures.contains(feature));

        return query.list(qProductConfiguration);
    }

    @Transactional
    public void insert(ProductConfiguration configuration) {
        entityManager.persist(configuration);

    }

    @Transactional
    public void deleteConfigurationForProduct(String productName, String configurationName) {
        ProductConfiguration configuration = findByNameAndProductName(productName, configurationName);
        entityManager.remove(configuration);
    }
}

