@Component
public class ConfigurationEvaluator {


    public EvaluationResult evaluateConfiguration(ProductConfiguration configuration, Set<FeatureConstraint> featureConstraints) {
        EvaluationResult result = new EvaluationResult();
        result = addEvaluationsToResult(result, configuration, featureConstraints);

        return result;
    }

    private EvaluationResult addEvaluationsToResult(EvaluationResult result, ProductConfiguration configuration, Set<FeatureConstraint> featureConstraints) {
        for (FeatureConstraint featureConstraint : featureConstraints) {
            result = featureConstraint.evaluateConfiguration(result, configuration);
        }

        if (result.isValid && !result.derivedFeatures.isEmpty()) {
            for (String derivedFeature : result.derivedFeatures) {
                configuration.active(derivedFeature);
                result.derivedFeatures.remove(derivedFeature);
                result = this.addEvaluationsToResult(result, configuration, featureConstraints);
            }

        }
        return result;
    }
}

@Repository
public class ProductsDAO {

    @PersistenceContext
    private EntityManager entityManager;

    QProduct qProduct = QProduct.product;
    QFeature qFeature = QFeature.feature;
    QFeatureConstraint qFeatureConstraint = QFeatureConstraint.featureConstraint;

    public List<Product> findAll() {
        JPAQuery query = new JPAQuery(entityManager);

        return query.from(qProduct).list(qProduct);
    }

    public Product findByName(String name) {
        JPAQuery query = new JPAQuery(entityManager);

        query.from(qProduct).where(qProduct.name.eq(name));
        Product product = query.singleResult(qProduct);
        if (product == null) {
            throw new ObjectNotFoundException(name);
        }
        return product;
    }

    @Transactional
    public void deleteByName(String productName) {
        Product product = findByName(productName);
        entityManager.remove(product);

    }

    @Transactional
    public void deleteConstraintsForProduct(String productName) {
        Product product = findByName(productName);
        for (FeatureConstraint featureConstraint : product.getProductFeatureConstraints()) {
            entityManager.remove(featureConstraint);
        }
        product.getProductFeatureConstraints().clear();
    }

    @Transactional
    public void insert(Product product) {
        entityManager.persist(product);
    }

    @Transactional
    public void insertFeature(Feature feature) {
        entityManager.persist(feature);
    }

    @Transactional
    public void deleteFeature(Feature feature) {
        JPADeleteClause deleteClause = new JPADeleteClause(entityManager, qFeature);
        deleteClause.where(qFeature.id.eq(feature.getId()));
        deleteClause.execute();
    }

    @Transactional
    public void insertConstraint(FeatureConstraint constraint) {
        entityManager.persist(constraint);
    }

    @Transactional
    public void deleteConstraintForProduct(String productName, Long constraintId) {
        JPADeleteClause deleteClause = new JPADeleteClause(entityManager, qFeatureConstraint);
        deleteClause.where(qFeatureConstraint.id.eq(constraintId));
        deleteClause.execute();
    }
}

@Entity
public class ConstraintExcludes extends FeatureConstraint {

    @Basic
    String sourceFeatureName;

    @Basic
    String excludedFeatureName;

    public ConstraintExcludes() {
    }

    public ConstraintExcludes(String sourceFeatureName, String excludedFeatureName) {
        this.sourceFeatureName = sourceFeatureName;
        this.excludedFeatureName = excludedFeatureName;
    }

    @Override
    public String getType() {
        return "excludes";
    }

    @Override
    public EvaluationResult evaluateConfiguration(EvaluationResult currentResult, ProductConfiguration configuration) {
        if (configuration.hasActiveFeature(sourceFeatureName) &&
                configuration.hasActiveFeature(excludedFeatureName)) {
            currentResult.isValid = false;
            currentResult.evaluationErrorMessages.add(String.format("Feauture %s can not be active when feature %s is active", excludedFeatureName, sourceFeatureName));
        }
        return currentResult;
    }

    public String getSourceFeatureName() {
        return sourceFeatureName;
    }

    public void setSourceFeatureName(String sourceFeatureName) {
        this.sourceFeatureName = sourceFeatureName;
    }

    public String getExcludedFeatureName() {
        return excludedFeatureName;
    }

    public void setExcludedFeatureName(String excludedFeatureName) {
        this.excludedFeatureName = excludedFeatureName;
    }
}

@Entity
public class ConstraintRequires extends FeatureConstraint {

    @Basic
    String sourceFeatureName;

    @Basic
    String requiredFeatureName;

    public ConstraintRequires() {
    }

    public ConstraintRequires(String sourceFeatureName, String requiredFeatureName) {
        this.sourceFeatureName = sourceFeatureName;
        this.requiredFeatureName = requiredFeatureName;
    }

    @Override
    public String getType() {
        return "requires";
    }

    // If sourceFeature is active, requiredFeature must be active too
    @Override
    public EvaluationResult evaluateConfiguration(EvaluationResult currentResult, ProductConfiguration configuration) {
        if (configuration.hasActiveFeature(sourceFeatureName) &&
                !configuration.hasActiveFeature(requiredFeatureName)) {
            currentResult.derivedFeatures.add(requiredFeatureName);
        }
        return currentResult;
    }

    public String getSourceFeatureName() {
        return sourceFeatureName;
    }

    public void setSourceFeatureName(String sourceFeatureName) {
        this.sourceFeatureName = sourceFeatureName;
    }

    public String getRequiredFeatureName() {
        return requiredFeatureName;
    }

    public void setRequiredFeatureName(String requiredFeatureName) {
        this.requiredFeatureName = requiredFeatureName;
    }
}

