    Set<Feature> productFeatures = new HashSet<Feature>();

    @OneToMany(mappedBy = "forProduct", fetch = FetchType.EAGER, cascade = CascadeType.ALL)
    Set<FeatureConstraint> productFeatureConstraints = new HashSet<FeatureConstraint>();

