        productFeatures.add(feature);
    }

    public void removeFeature(Feature feature) {
        productFeatures.remove(feature);
    }

    public static Product buildWithFeatures(String... featureNames) {
        Product product = new Product();
        for (String featureName : featureNames) {
            product.addFeature(Feature.withName(product, featureName));
        }

        return product;

    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    @JsonProperty("constraints")
    public Set<FeatureConstraint> getProductFeatureConstraints() {
        return productFeatureConstraints;
    }

    public Feature findProductFeatureByName(String featureName) {
        for (Feature feature : getProductFeatures()) {
            if (feature.name.equalsIgnoreCase(featureName)) {
                return feature;
            }
        }

        throw new ObjectNotFoundException(featureName);
    }

    public boolean hasFeatureNamed(String featureName) {
        for (Feature feature : getProductFeatures()) {
            if (feature.name.equalsIgnoreCase(featureName)) {
                return true;
            }
        }

        return false;
    }

    public void addFeatureConstraint(FeatureConstraint constraint) {
        productFeatureConstraints.add(constraint);
    }
}

@Entity
public class ProductConfiguration {

    @Id
    @GeneratedValue
    Long id;

    @Column(nullable = false)
    String name;

    @Column
    Boolean valid = true;

    @JsonIgnore
    @ManyToOne
    Product product;

    @ManyToMany(fetch = FetchType.EAGER)
    Set<Feature> activedFeatures = new HashSet<Feature>();

    public Set<Feature> getActivedFeatures() {
        return activedFeatures;
    }

    public Set<String> availableFeatures() {
        return collectFeatureNames(product.getProductFeatures());
    }

    private Set<String> collectFeatureNames(Set<Feature> featuresSet) {
        Set<String> features = new HashSet<String>();
        for (Feature feature : featuresSet) {
            features.add(feature.name);
        }

        return features;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public Product getProduct() {
        return product;
    }

    public void setProduct(Product product) {
        this.product = product;
    }

    public Set<String> activedFeatures() {
        return collectFeatureNames(activedFeatures);
    }

    public Boolean isValid() {
        return valid;
    }

    public void setValid(Boolean valid) {
        this.valid = valid;
    }

    public void active(Feature feature) {
        activedFeatures.add(feature);

    }

    public void deactive(Feature feature) {
        activedFeatures.remove(feature);
    }

    public void active(String featureName) {
        Feature feature = product.findProductFeatureByName(featureName);
        active(feature);
    }

    public void deactive(String featureName) {
        Feature feature = product.findProductFeatureByName(featureName);
        deactive(feature);
    }

    public boolean hasActiveFeature(String featureName) {
        return activedFeatures().contains(featureName);
    }
}

@Repository
public class ProductsConfigurationsDAO {

    @PersistenceContext
    private EntityManager entityManager;

    QProductConfiguration qProductConfiguration = QProductConfiguration.productConfiguration;
    QProduct qProduct = QProduct.product;

    public List<ProductConfiguration> findByProductName(String productName) {


        JPAQuery query = new JPAQuery(entityManager);
        query.from(qProductConfiguration)
                .innerJoin(qProductConfiguration.product, qProduct)
                .where(qProduct.name.eq(productName));
        return query.list(qProductConfiguration);
    }

    public ProductConfiguration findByNameAndProductName(String productName, String configurationName) {
        QProduct qProduct = QProduct.product;


        JPAQuery query = new JPAQuery(entityManager);
        query.from(qProductConfiguration)
                .innerJoin(qProductConfiguration.product, qProduct)
                .where(qProduct.name.eq(productName)
                        .and(qProductConfiguration.name.eq(configurationName)));
        return query.singleResult(qProductConfiguration);
    }

    @Transactional
    public void deleteConfigurationsForProduct(String productName) {
        for (ProductConfiguration productConfiguration : findByProductName(productName)) {
            entityManager.remove(productConfiguration);
        }

    }

    public List<ProductConfiguration> findConfigurationsWithFeatureActive(Feature feature) {
        JPAQuery query = new JPAQuery(entityManager);
        query.from(qProductConfiguration)
                .where(qProductConfiguration.activedFeatures.contains(feature));

        return query.list(qProductConfiguration);
    }

    @Transactional
    public void insert(ProductConfiguration configuration) {
        entityManager.persist(configuration);

    }

    @Transactional
    public void deleteConfigurationForProduct(String productName, String configurationName) {
        ProductConfiguration configuration = findByNameAndProductName(productName, configurationName);
        entityManager.remove(configuration);
    }
}

